-- =============================================================================
-- CONFIGURACIÓN DE MENÚS POR ROL - PERSONALIZADO POR FUNCIÓN
-- Fecha: 2026-06-10
-- Descripción: Menús específicos para cada rol según sus responsabilidades
-- =============================================================================

-- LIMPIAR CONFIGURACIONES EXISTENTES (Opcional - descomentar si se requiere)
-- DELETE FROM LOGISTICA_ConfiguracionPermiso WHERE clave IN ('MENU_TYPE','MENU_JSON','LAYOUT_ACCORDION') AND idrol IN ('ADLOGIST','OPLOGIST','TILOGIST','APLOGIST','JEMLOGIST','LOLOGIST','EMLOGIST','ALLOGIST','FINANZAS','GERENTE');

-- 1. ADLOGIST - Admin Logística (TODO el menú completo)

-- 2. TILOGIST - Admin Sistema (TODO + Administración)

-- 3. OPLOGIST - Operativo Campo (Requerimientos y Saldo)

-- 4. LOLOGIST - Operador Logística (Compras, Consolidación, OC, OS)

-- 5. EMLOGIST - Operador Licitaciones (Requerimientos, Cotizaciones)

-- 6. JEMLOGIST - Jefe Licitaciones (Compras + Aprobaciones)

-- 7. ALLOGIST - Almacén (Despachos, Recepción, Kardex)

-- 8. APLOGIST - Aprobador (Aprobaciones y Reportes)

-- 9. FINANZAS (Aprobaciones y Reportes)

-- 10. GERENTE (Dashboard, Aprobaciones, Reportes - Vista resumen)

-- =============================================================================
-- VERIFICACIÓN FINAL
-- =============================================================================
SELECT 
    idrol,
    COUNT(*) as total_configs,
    MAX(CASE WHEN clave='MENU_TYPE' THEN valor END) as menu_type,
    MAX(CASE WHEN clave='LAYOUT_ACCORDION' THEN valor END) as layout_accordion
FROM LOGISTICA_ConfiguracionPermiso
WHERE clave IN ('MENU_TYPE','MENU_JSON','LAYOUT_ACCORDION')
GROUP BY idrol
ORDER BY idrol;

-- Total de roles configurados
PRINT 'Total de roles configurados: 10 (ADLOGIST, TILOGIST, OPLOGIST, LOLOGIST, EMLOGIST, JEMLOGIST, ALLOGIST, APLOGIST, FINANZAS, GERENTE)';
PRINT 'NOTA: JLOLOGIST no se configura aqui (tiene menu especial hardcodeado)';
